/bin/bash -lc "python - <<'PY'
from bioblend.galaxy.histories import HistoryClient
import inspect
for n in dir(HistoryClient):
 if 'copy' in n.lower() or 'content' in n.lower():
  x=getattr(HistoryClient,n)
  if callable(x):
   try: print(n, inspect.signature(x))
   except: pass
PY"

